const tableBody = document.getElementById("operators-table-body");const emptyState = document.getElementById("operators-empty");const statusEl = document.getElementById("operators-status");const summaryEl = document.getElementById("operators-summary");const updatedEl = document.getElementById("operators-updated");const refreshButton = document.getElementById("btn-refresh");const themeButton = document.getElementById("btn-theme");function escapeHtml(value){return String(value ?? "") .replace(/&/g,"&amp;") .replace(/</g,"&lt;") .replace(/>/g,"&gt;") .replace(/"/g,"&quot;") .replace(/'/g,"&#39;");} function setStatus(ok,text){if (!statusEl) return;statusEl.className = "result";if (ok === true){statusEl.className += " ok";} else if (ok === false){statusEl.className += " err";} statusEl.textContent = text || "";} function setThemeDark(enabled){document.documentElement.classList.toggle("dark",enabled);if (themeButton){const icon = themeButton.querySelector(".material-icons-outlined");if (icon){icon.textContent = enabled ? "light_mode" :"dark_mode";}} try{localStorage.setItem("themeDark",enabled ? "1" :"0");} catch (err){}} if (themeButton){themeButton.addEventListener("click",() =>{setThemeDark(!document.documentElement.classList.contains("dark"));});try{const saved = localStorage.getItem("themeDark");if (saved === "1"){setThemeDark(true);}} catch (err){}} function buildInput(value,type = "text"){const input = document.createElement("input");input.type = type;input.value = value || "";input.className = "w-full bg-gray-100 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg px-2 py-1 text-xs";return input;} function buildRow(operator){const row = document.createElement("tr");row.className = "border-b border-border-light dark:border-border-dark";const userCell = document.createElement("td");userCell.className = "py-3 px-3";const userName = document.createElement("div");userName.className = "font-semibold text-gray-900 dark:text-gray-100";userName.innerHTML = escapeHtml(operator.username || ("operator-" + operator.id));const userMeta = document.createElement("div");userMeta.className = "text-xs text-gray-500";userMeta.textContent = "ID " + operator.id;userCell.appendChild(userName);userCell.appendChild(userMeta);row.appendChild(userCell);const displayCell = document.createElement("td");displayCell.className = "py-3 px-3";const displayInput = buildInput(operator.display_name || "");displayCell.appendChild(displayInput);row.appendChild(displayCell);const emailCell = document.createElement("td");emailCell.className = "py-3 px-3";const emailInput = buildInput(operator.email || "");emailCell.appendChild(emailInput);row.appendChild(emailCell);const hourlyCell = document.createElement("td");hourlyCell.className = "py-3 px-3";const hourlyInput = buildInput(operator.hourly_limit || "","number");hourlyInput.min = "1";hourlyInput.step = "1";hourlyCell.appendChild(hourlyInput);row.appendChild(hourlyCell);const dailyCell = document.createElement("td");dailyCell.className = "py-3 px-3";const dailyInput = buildInput(operator.daily_limit || "","number");dailyInput.min = "1";dailyInput.step = "1";dailyCell.appendChild(dailyInput);row.appendChild(dailyCell);const statsCell = document.createElement("td");statsCell.className = "py-3 px-3 text-xs text-gray-500 dark:text-gray-400";const sentHour = operator.sent_last_hour || 0;const sentDay = operator.sent_last_day || 0;statsCell.textContent = sentHour + " / " + sentDay;row.appendChild(statsCell);const actionCell = document.createElement("td");actionCell.className = "py-3 px-3";const saveButton = document.createElement("button");saveButton.className = "btn primary";saveButton.textContent = "Save";const rowStatus = document.createElement("div");rowStatus.className = "result";rowStatus.textContent = "";actionCell.appendChild(saveButton);actionCell.appendChild(rowStatus);row.appendChild(actionCell);saveButton.addEventListener("click",async () =>{const hourlyValue = Number(hourlyInput.value);if (!Number.isFinite(hourlyValue) || hourlyValue < 1){rowStatus.className = "result err";rowStatus.textContent = "Hourly limit must be >= 1";return;} const dailyValue = Number(dailyInput.value);if (!Number.isFinite(dailyValue) || dailyValue < 1){rowStatus.className = "result err";rowStatus.textContent = "Daily limit must be >= 1";return;} const payload ={display_name:displayInput.value.trim(),email:emailInput.value.trim(),hourly_limit:Math.floor(hourlyValue),daily_limit:Math.floor(dailyValue)};rowStatus.className = "result";rowStatus.textContent = "Saving...";try{const res = await fetch(`/api/ui/operators/${operator.id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const data = await res.json().catch(() => ({}));if (!res.ok){rowStatus.className = "result err";rowStatus.textContent = data.detail || "Save failed";return;} rowStatus.className = "result ok";rowStatus.textContent = "Saved";if (data.operator){displayInput.value = data.operator.display_name || "";emailInput.value = data.operator.email || "";hourlyInput.value = data.operator.hourly_limit || "";dailyInput.value = data.operator.daily_limit || "";}} catch (err){rowStatus.className = "result err";rowStatus.textContent = "Save failed";}});return row;} function renderOperators(operators){if (!tableBody) return;tableBody.innerHTML = "";if (!operators || operators.length === 0){if (emptyState) emptyState.style.display = "block";if (summaryEl) summaryEl.textContent = "Operators:0";return;} if (emptyState) emptyState.style.display = "none";operators.forEach(op =>{tableBody.appendChild(buildRow(op));});const totalHour = operators.reduce((sum,op) => sum + (op.sent_last_hour || 0),0);const totalDay = operators.reduce((sum,op) => sum + (op.sent_last_day || 0),0);if (summaryEl){summaryEl.textContent = `Operators:${operators.length} | Sent last hour:${totalHour} | Sent last day:${totalDay}`;}} async function refreshOperators(){setStatus(null,"Loading...");try{const res = await fetch("/api/ui/operators");const data = await res.json().catch(() => ({}));if (!res.ok){setStatus(false,data.detail || "Failed to load operators");return;} renderOperators(data.operators || []);const now = new Date().toISOString().replace("T"," ").replace("Z"," UTC");if (updatedEl) updatedEl.textContent = "Updated:" + now;setStatus(true,"Loaded");} catch (err){setStatus(false,"Failed to load operators");}} if (refreshButton){refreshButton.addEventListener("click",refreshOperators);} refreshOperators();
